// Розбір оновлення від Telegram. Telegram шле багато типів подій —
// беремо лише ті три, що нас цікавлять, решту тихо ігноруємо.

const u = $input.first().json.body || $input.first().json || {};

// Кнопки мають покривати весь робочий день, а не лише обʼєкти. Зустріч із
// замовником чи субпідрядником так само часто відбувається в кафе, на парковці
// або за адресою, якої немає серед geofence - і без своєї кнопки така поїздка
// лишалася без типу назавжди.
//
// purpose - мета, яку кнопка описує сама; ставимо її одразу, щоб поїздка не
// зависла з типом, але без мети. Де мету не вивести з кнопки, hint каже, що
// саме написати у відповідь.
const ACTION = {
  est: { classification: 'business', label: 'Оцінка/замір',    ask_purpose: true,
         hint: 'Відповідь на це повідомлення = чий обʼєкт і що міряли' },
  job: { classification: 'business', label: 'Обʼєкт у роботі',  ask_purpose: true,
         hint: 'Відповідь на це повідомлення = який обʼєкт і що робили' },
  mtg: { classification: 'business', label: 'Зустріч',         ask_purpose: true,
         hint: 'Відповідь на це повідомлення = з ким і про що зустріч' },
  sup: { classification: 'business', label: 'Постачальник',    ask_purpose: false,
         purpose: 'закупівля у постачальника' },
  oth: { classification: 'business', label: 'Інше по роботі',  ask_purpose: true,
         hint: 'Відповідь на це повідомлення = що це була за поїздка' },
  per: { classification: 'personal', label: 'Особисте',        ask_purpose: false }
};

if (u.callback_query) {
  const cq = u.callback_query;
  const m = /^c:(\d+):(est|job|mtg|sup|oth|per)$/.exec(cq.data || '');
  if (!m) return [{ json: { kind: 'other' } }];
  const a = ACTION[m[2]];
  return [{ json: {
    kind: 'callback',
    callback_query_id: cq.id,
    tg_user_id: cq.from && cq.from.id,
    tg_user_name: [cq.from && cq.from.first_name, cq.from && cq.from.last_name].filter(Boolean).join(' '),
    chat_id: cq.message && cq.message.chat && cq.message.chat.id,
    message_id: cq.message && cq.message.message_id,
    original_text: (cq.message && cq.message.text) || '',
    trip_id: Number(m[1]),
    classification: a.classification,
    action_label: a.label,
    ask_purpose: a.ask_purpose,
    purpose_hint: a.hint || null,
    purpose_default: a.purpose || ''
  } }];
}

const msg = u.message || u.edited_message;
if (!msg) return [{ json: { kind: 'other' } }];

const base = {
  tg_user_id: msg.from && msg.from.id,
  chat_id: msg.chat && msg.chat.id,
  message_id: msg.message_id,
  taken_at: new Date((msg.date || 0) * 1000).toISOString()
};

// Голе число = показник одометра. Найменша можлива дія: набрати 47385 - і все.
// Мета поїздки завжди слово, тож сплутати неможливо, а відповідати на щось
// тут зайве: водій стоїть біля авто, а не гортає переписку.
const bare = /^\s*(\d{4,7})\s*(?:км|km)?\s*$/i.exec(msg.text || '');
if (bare && !msg.reply_to_message) {
  return [{ json: { ...base, kind: 'odometer', odometer_km: Number(bare[1]) } }];
}

// Відповідь на картку поїздки = мета цієї поїздки
if (msg.reply_to_message && msg.text) {
  return [{ json: { ...base, kind: 'purpose',
                    reply_to_message_id: msg.reply_to_message.message_id,
                    purpose: msg.text.trim().slice(0, 300) } }];
}

// Знімок приходить двома різними полями, і це не косметика. "Фото" Telegram
// стискає і зрізає EXIF; "файл" зберігає оригінал разом із часом зйомки, а для
// одометра саме час і є доказом. Доки гілка читала лише msg.photo, кожен
// надісланий файлом одометр зникав мовчки - навіть без відповіді водієві.
let media = null;
if (Array.isArray(msg.photo) && msg.photo.length) {
  media = { file_id: msg.photo[msg.photo.length - 1].file_id, file_name: null };
} else if (msg.document && /^image\//i.test(msg.document.mime_type || '')) {
  media = { file_id: msg.document.file_id, file_name: msg.document.file_name || null };
}

if (media) {
  const hay = ((msg.caption || '') + ' ' + (media.file_name || '')).toLowerCase();
  let kind = 'site';
  if (/одометр|odometer|пробіг/.test(hay)) kind = 'odometer';
  else if (/чек|receipt|пальн|fuel/.test(hay)) kind = 'receipt';
  const num = /(\d{4,7})/.exec(msg.caption || '');
  return [{ json: { ...base, kind: 'photo', photo_kind: kind,
                    file_id: media.file_id,
                    file_name: media.file_name,
                    odometer_km: (kind === 'odometer' && num) ? Number(num[1]) : null,
                    caption: msg.caption || null } }];
}

return [{ json: { ...base, kind: 'other' } }];

// Підтвердження у картці + підказка, що робити далі
const src = $('Розбір оновлення').first().json;
const db  = $input.first().json || {};

const mark = db.classification === 'personal' ? '🏠' : '💼';
const lines = [
  src.original_text,
  '',
  `${mark} <b>${src.action_label}</b> · ${db.driver_label || '—'}`
];
// Підказка залежить від кнопки: «з ким і про що» після зустрічі корисніше
// за загальне «мета поїздки», бо саме це питатимуть при перевірці.
if (src.purpose_hint) lines.push(`<i>${src.purpose_hint}</i>`);
if (db.account_known === false) {
  lines.push(`<i>Акаунт ${src.tg_user_name || src.tg_user_id} ще не привʼязаний до водія — скажи Роману.</i>`);
}

return [{ json: {
  chat_id: src.chat_id,
  message_id: src.message_id,
  callback_query_id: src.callback_query_id,
  toast: src.ask_purpose ? 'Записано. Додай мету відповіддю.' : 'Записано.',
  new_text: lines.join('\n')
} }];

// ON CONFLICT DO NOTHING на дублі file_id віддає 0 рядків, але alwaysOutputData
// у 'Зберегти фото' все одно шле далі порожній item — інакше вся гілка обривається
// ще на INSERT і 'Підтвердити фото' взагалі не спрацьовує. Тут явно перевіряємо:
// id є — це новий запис, ведемо його на завантаження й Nextcloud; id немає — дубль,
// нічого не тягнемо і нічого не пишемо, це правильна поведінка.
const it = $input.first();
if (!it || it.json.id == null) return [];
return [it];

// Гілка для чеків: далі йде лише те, що водій підписав/розпізнав як чек.
// Все інше (фото обʼєкта, одометра) сюди не заходить — receipt-bot на LXC 414
// сам розпізнає вміст через ROG vision, дублювати цю класифікацію не треба.
const kind = $('Розбір оновлення').item.json.photo_kind;
if (kind !== 'receipt') return [];
return $input.all();

// Звірка одометра з GPS. Сенс не в точності до кілометра, а в тому, щоб
// розходження потрапляло водієві на очі щоразу, поки його ще можна пояснити.
// Для GPS-трекінгу недобір 2-5% - норма; більше означає непройдені поїздки.
const r   = $input.first().json;
const src = $('Розбір оновлення').first().json;

const lines = [`📟 Одометр <b>${r.odometer_km}</b> км записано.`];

if (r.prev_km == null) {
  lines.push('<i>Перша точка відліку. Розходження порахую з наступного зчитування.</i>');
} else {
  const odo = Number(r.odo_delta);
  const gps = Number(r.gps_km);
  const gap = odo - gps;
  const pct = odo > 0 ? (gap / odo) * 100 : 0;
  lines.push(`Від ${r.prev_on}: одометр <b>${odo}</b> км · GPS <b>${gps}</b> км`);
  if (Math.abs(pct) <= 5) {
    lines.push(`✅ Не враховано ${gap.toFixed(1)} км (${pct.toFixed(0)}%) — у межах норми.`);
  } else {
    lines.push(`⚠️ Не враховано <b>${gap.toFixed(1)}</b> км (${pct.toFixed(0)}%).`);
    lines.push('<i>Більше за норму. Такі кілометри при перевірці рахуються як особисті.</i>');
  }
}

return [{ json: { chat_id: src.chat_id, message_id: src.message_id,
                  text: lines.join('\n') } }];
